let defaults: ClientConfig = { ...DEFAULTS };
let client: Client = createClient();

/**
 * Merges into the configuration the module-level functions use, so a base
 * URL and an interceptor can be set from different places.
 */
export function configure(next: Partial<ClientConfig>): void {
  defaults = { ...defaults, ...next };
  client = createClient(defaults);
}

export function currentConfig(): ClientConfig {
  return defaults;
}

/** The client `configure()` maintains, which hooks and other consumers default to. */
export function defaultClient(): Client {
  return client;
}

/**
 * List pets
 * 
 * Lists pets, filtered and capped.
 * 
 * The one operation offered in four representations. Each `@response 200`
 * tag adds a media type to the *same* response object, so the document says
 * one 200 with four `content` entries.
 */
export const list: Client["list"] = (options, callOptions) => client.list(options, callOptions);

/**
 * Add a pet
 * 
 * Adds a pet to the store and publishes a change event.
 */
export const add: Client["add"] = (options, callOptions) => client.add(options, callOptions);

/**
 * Fetch a pet
 * 
 * Fetches one pet as JSON or as protobuf.
 * 
 * The protobuf representation is encoded by `encodeProto<Pet>`, generated
 * from the same `@fieldNumber` declarations as `build/schemas/petstore.proto`.
 */
export const get: Client["get"] = (options, callOptions) => client.get(options, callOptions);

/**
 * Remove a pet
 * 
 * Removes a pet. No body, so no content.
 */
export const remove: Client["remove"] = (options, callOptions) => client.remove(options, callOptions);

/**
 * Sell a pet
 * 
 * Sells a pet to an owner and publishes a change event.
 */
export const sell: Client["sell"] = (options, callOptions) => client.sell(options, callOptions);
